# One Postgres schema (Supabase in production) shared by the offline
# pipeline, which writes it, and the deployed API/MCP server, which reads it.
# Every statement is idempotent, so init_db() is safe to run on every
# script start.
#
# Ids are GENERATED BY DEFAULT rather than ALWAYS so that
# scripts/import_published_reports.py can carry over the existing ids.
# That keeps every finding_id anyone has already cited stable.
SCHEMA_DDL = """
CREATE TABLE IF NOT EXISTS filings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cik BIGINT NOT NULL,
    ticker TEXT NOT NULL,
    form_type TEXT NOT NULL,
    filing_date DATE NOT NULL,
    accession_number TEXT NOT NULL UNIQUE,
    source_url TEXT NOT NULL,
    fetched_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS sections (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    filing_id BIGINT NOT NULL REFERENCES filings(id) ON DELETE CASCADE,
    item_key TEXT NOT NULL,
    heading_text TEXT NOT NULL,
    body_text TEXT NOT NULL,
    UNIQUE (filing_id, item_key)
);

CREATE INDEX IF NOT EXISTS idx_sections_filing_id ON sections(filing_id);
CREATE INDEX IF NOT EXISTS idx_filings_ticker ON filings(ticker);

CREATE TABLE IF NOT EXISTS findings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    older_filing_id BIGINT NOT NULL REFERENCES filings(id) ON DELETE CASCADE,
    newer_filing_id BIGINT NOT NULL REFERENCES filings(id) ON DELETE CASCADE,
    item_key TEXT NOT NULL,
    category TEXT NOT NULL,
    tier TEXT NOT NULL,
    reasoning TEXT NOT NULL,
    older_excerpt TEXT,
    newer_excerpt TEXT,
    excerpt_verified BOOLEAN NOT NULL,
    confidence DOUBLE PRECISION NOT NULL,
    verifier_reasoning TEXT NOT NULL,
    final_tier TEXT NOT NULL,
    classifier_model TEXT NOT NULL,
    classifier_prompt_version TEXT NOT NULL,
    verifier_model TEXT NOT NULL,
    verifier_prompt_version TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_findings_older_filing_id ON findings(older_filing_id);
CREATE INDEX IF NOT EXISTS idx_findings_newer_filing_id ON findings(newer_filing_id);

CREATE TABLE IF NOT EXISTS llm_cache (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cache_key TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL,
    output_json TEXT NOT NULL,
    model TEXT NOT NULL,
    prompt_version TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
);

-- Supabase automatically serves every table in the public schema over its
-- PostgREST API to anyone holding the project's (public) anon key. RLS with
-- no policies denies that path entirely. Our own code connects as the
-- table owner (postgres), which bypasses RLS, so nothing else changes.
ALTER TABLE filings ENABLE ROW LEVEL SECURITY;
ALTER TABLE sections ENABLE ROW LEVEL SECURITY;
ALTER TABLE findings ENABLE ROW LEVEL SECURITY;
ALTER TABLE llm_cache ENABLE ROW LEVEL SECURITY;
"""
